arguments.command:
cd /tmp/sv-eee122fe825e4f38aba049219defd8a8/moderate-version-conflicts && dotnet package list --format json 2>/dev/null | python3 -c "import sys,json; d=json.load(sys.stdin); json.dump(d,open('after-cpm-packages.json','w'),indent=2)" && python3 -c "
import json
baseline = json.load(open('baseline-packages.json'))
after = json.load(open('after-cpm-packages.json'))

def extract(data):
    result = {}
    for proj in data.get('projects', []):
        pname = proj['path'].split('/')[-1]
        pkgs = {}
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                pkgs[pkg['id']] = (pkg.get('requestedVersion',''), pkg.get('resolvedVersion',''))
        result[pname] = pkgs
    return result

b = extract(baseline)
a = extract(after)

print('=== CHANGES ===')
changes = False
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(pkg)
        av = ap.get(pkg)
        if bv != av:
            changes = True
            print(f'  {proj}: {pkg} {bv} -> {av}')
if not changes:
    print('  (none)')

print('=== UNCHANGED ===')
for proj in sorted(b.keys()):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    for pkg in sorted(bp.keys()):
        if bp.get(pkg) == ap.get(pkg):
            print(f'  {proj}: {pkg} {bp[pkg]}')
" 2>&1

